INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (1,'VT-0001','Cidade de Deus','Cidade de Deus',2002,'Fernando Meirelles','Drama','130 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/gfnXixcGC060QcG6JPxN6AMdVsq.jpg','available','Estante A1','Buscapé é um jovem morador da Cidade de Deus que cresce em meio à violência. Com medo de se tornar um bandido, enxerga na fotografia uma oportunidade de ter uma vida digna.','Alexandre Rodrigues, Leandro Firmino, Phellipe Haagensen, Douglas Silva','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/uvitbjFU4JqvMwIkMWHp69bmUzG.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (2,'VT-0002','Central do Brasil','Central do Brasil',1998,'Walter Salles','Drama','110 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/qfyWFhUhqeNRU9HmCaBDAxVKRZ9.jpg','available','Estante A2','Dora escreve cartas para analfabetos na estação Central do Brasil. Uma das clientes de Dora é Ana, que vem escrever uma carta com o seu filho, Josué, um garoto de nove anos, que sonha encontrar o pai que nunca conheceu. Na saída da estação, Ana é atropelada e Josué fica abandonado. Mesmo a contragosto, Dora acaba acolhendo o menino e envolvendo-se com ele. Termina por levar Josué para o interior do Nordeste, à procura do pai. À medida em que vão entrando país adentro, esses dois personagens, tão diferentes, vão se aproximando... Começa então uma viagem fascinate ao coração do Brasil, à procura do pai desaparecido, e uma viagem profundamente emotiva ao coração de cada um dos personagens do filme.','Fernanda Montenegro, Vinícius de Oliveira, Marília Pêra, Othon Bastos','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/lrLIy9OFRQg4VkhrCyolfNXJEUH.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (3,'VT-0003','Parasita','기생충',2019,'Bong Joon-ho','Comédia','132 min','English','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/bNGW8zYA91VqTZfV3jnKHPEKKvB.jpg','available','Estante A3','Toda a família de Ki-taek está desempregada, vivendo num porão sujo e apertado. Uma obra do acaso faz com que o filho adolescente da família comece a dar aulas de inglês à garota de uma família rica. Fascinados com a vida luxuosa destas pessoas, pai, mãe, filho e filha bolam um plano para se infiltrarem também na família glamorosa, um a um. No entanto, os segredos e mentiras necessários à ascensão social custarão caro a todos.','Song Kang-ho, Lee Sun-kyun, Cho Yeo-jeong, Woo-sik Choi','South Korea','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/TU9NIjwzjoKPwQHoHshkFcQUCG.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (4,'VT-0004','O Auto da Compadecida','O Auto da Compadecida',2000,'Guel Arraes','Comédia','104 min','Latin','Livre','DVD','https://image.tmdb.org/t/p/w500/y3IhuITELtprMhUd7bccu629rba.jpg','available','Estante A4','As aventuras dos nordestinos João Grilo, um sertanejo pobre e mentiroso, e Chicó, o mais covarde dos homens. Ambos lutam pelo pão de cada dia e atravessam por vários episódios enganando a todos do pequeno vilarejo de Taperoá, no sertão da Paraíba. A salvação da dupla acontece com a aparição da Nossa Senhora. Adaptação da obra de Ariano Suassuna.','Matheus Nachtergaele, Selton Mello, Fernanda Montenegro, Rogério Cardoso','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/alQqTpmEkxSLgajfEYTsTH6nAKB.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (5,'VT-0005','2001: Uma Odisseia no Espaço','2001: A Space Odyssey',1968,'Stanley Kubrick','Ficção científica','148 min','English','Livre','Digital','https://image.tmdb.org/t/p/w500/pVCmLuATJ0lQs4Vx1zUJUN0if2A.jpg','available','Estante A5','Desde a “Aurora do Homem” (a pré-história), um misterioso monólito negro parece emitir sinais de outra civilização, assim interferindo no nosso planeta. Quatro milhões de anos depois, no século XXI, uma equipe de astronautas liderados pelo experiente David Bowman e Frank Poole é enviada ao planeta Júpiter para investigar o enigmático monólito na nave Discovery, totalmente controlada pelo computador HAL-9000. Entretanto, no meio da viagem, HAL-9000 entra em pane e tenta assumir o controle da nave, eliminando um a um os tripulantes.','Keir Dullea, Gary Lockwood, William Sylvester, Douglas Rain','United Kingdom','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/w5IDXtifKntw0ajv2co7jFlTQDM.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (6,'VT-0006','Bacurau','Bacurau',2019,'Juliano Dornelles, Kleber Mendonça Filho','Mistério','131 min','Português','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/qvmLAVqNB5TbGUa9QqQvXiFC4UR.jpg','available','Estante A6','Num futuro recente, Bacurau, um povoado do sertão de Pernambuco, some misteriosamente do mapa. Quando uma série de assassinatos inexplicáveis começam a acontecer, os moradores da cidade tentam reagir. Mas como se defender de um inimigo desconhecido e implacável?','Bárbara Colen, Thomás Aquino, Silvero Pereira, Sonia Braga','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/nhsC7Q1Zb5n2p4H3UKy422zP5XC.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (7,'VT-0007','Deus e o Diabo na Terra do Sol','Deus e o Diabo na Terra do Sol',1964,'Glauber Rocha','Aventura','120 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/vBSTJhHcVq5zffTudQ7jMG9vDwI.jpg','available','Estante A7','Manuel vive com a esposa Rosa e a mãe, numa vida muito pobre no sertão brasileiro. Numa discussão com o Coronel que controla sua região o rapaz se revolta e mata o poderoso. Sua única opção é fugir deixando o pouco que tem para trás e seguindo o beato Sebastião que promete a bênção de Deus aos seus fiéis. Manuel pode, sem querer, estar novamente entrando em problemas, pois a oligarquia local encomendou a morte de Sebastião e seus seguidores a João das Mortes, com medo que uma situação como a de Canudos se repita.','Geraldo del Rey, Yoná Magalhães, Othon Bastos, Sonia dos Humildes','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/sDKHdt84JGzfxAJp2vqLdVzPj0Y.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (8,'VT-0008','Vidas Secas','Vidas Secas',1963,'Nelson Pereira dos Santos','Drama','103 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/Ag7TYDyQ1IoHzaegGr0cooiy8Xu.jpg','available','Estante A8','Uma família miserável tenta escapar da seca no sertão nordestino. Fabiano (Átila Iório), Sinhá Vitória (Maria Ribeiro), seus dois filhos e a cachorra Baleia vagam sem destino e já quase sem esperanças pelos confins do interior, sobrevivendo às forças da natureza e à crueldade dos homens. Adaptação da obra de Graciliano Ramos.','Átila Iório, Maria Ribeiro, Baleia, Gilvan Lima','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/3KBuZG9keFgKAbIRnMMn4MoOzo7.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (9,'VT-0009','O Pagador de Promessas','O Pagador de Promessas',1962,'Anselmo Duarte','Drama','92 min','Português','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/wqxzal8qzNi97iaSSSBQVAsNsyl.jpg','available','Estante B1','Zé do Burro e sua esposa Rosa vivem em uma pequena propriedade rural próxima de Salvador. Um dia, o burro de estimação de Zé é atingido por um raio e ele acaba indo a um terreiro de candomblé, onde faz uma promessa para salvar o animal. Com o restabelecimento do bicho, Zé põe-se a cumprir a promessa e doa metade de seu sítio, para depois começar uma caminhada rumo a Salvador, carregando nas costas uma imensa cruz de madeira. Mas a via crucis de Zé ainda se torna mais angustiante ao ver Rosa se envolver com o cafetão Bonitão e ao ser impedido por Padre Olavo de entrar em sua igreja, pela razão de Zé ter feito sua promessa em um terreiro.','Leonardo Villar, Glória Menezes, Dionísio Azevedo, Geraldo del Rey','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/k13mFZr51lcOxvLrHHCk9Llevcf.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (10,'VT-0010','Terra em Transe','Terra em Transe',1967,'Glauber Rocha','Drama','108 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/5xSNXpjMRgaJhpWHiGeWxaRKBxD.jpg','available','Estante B2','No hipotético país latino-americano Eldorado, o poeta e jornalista idealista e anarquista Paulo Martins luta contra o governador populista e o presidente conservador, apoiado pelas forças revolucionárias. Paulo fica dividido entre a loucura da elite e a submissão cega das massas.','Jardel Filho, Paulo Autran, José Lewgoy, Glauce Rocha','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/xCSzJsUmgd61nXjxoslbWOgOlbY.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (11,'VT-0011','Pixote: A Lei do Mais Fraco','Pixote: A Lei do Mais Fraco',1980,'Héctor Babenco','Crime','128 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/g5NxPFGcoUCXOrHx9DHi6AAQWQu.jpg','available','Estante B3','Aos 11 anos, um menor abandonado foge do reformatório, onde aprendeu muito sobre o crime, para viver nas ruas. Ele sobrevive atuando como traficante, assassino e até cafetão.','Fernando Ramos da Silva, Jorge Julião, Gilberto Moura, Edilson Lino','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/88SnnUEY4CmUJTjzhqYfY3zffEC.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (12,'VT-0012','Eles Não Usam Black-Tie','Eles Não Usam Black-Tie',1981,'Leon Hirszman','Drama','122 min','Português','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/r0jXCh59NOJaFKtf9tqglIm3n7N.jpg','available','Estante B4','Em São Paulo, em 1980, o jovem operário Tião e sua namorada Maria decidem casar-se ao saber que a moça está grávida. Ao mesmo tempo, eclode um movimento grevista que divide a categoria metalúrgica. Preocupado com o casamento e temendo perder o emprego, Tião fura a greve, entrando em conflito com o pai, Otávio, um velho militante sindical que passou três anos na cadeia durante o regime militar','Carlos Alberto Riccelli, Bete Mendes, Fernanda Montenegro, Gianfrancesco Guarnieri','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/7qoRAL3ceJ5LH0pZ0KxkqkC0JMW.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (13,'VT-0013','O Som ao Redor','O Som ao Redor',2012,'Kleber Mendonça Filho','Thriller','131 min','普通话','Livre','DVD','https://image.tmdb.org/t/p/w500/1kdTL3IvaTg3PqeRqYmE3Q1ESb4.jpg','maintenance','Estante B5','A vida numa rua de classe média na zona sul do Recife toma um rumo inesperado, após a chegada de uma milícia que oferece a paz de espírito da segurança particular. A presença desses homens traz tranquilidade para alguns, e tensão para outros, numa comunidade que parece temer muita coisa. Enquanto isso, Bia (Maeve Jinkings), casada e mãe de duas crianças, precisa achar uma maneira de lidar com os latidos constantes do cão de seu vizinho.','Irandhir Santos, Gustavo Jahn, Maeve Jinkings, W.J. Solha','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/xJQsDKD6ZfQ9nJGtuKB4N878REq.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (14,'VT-0014','Aquarius','Aquarius',2016,'Kleber Mendonça Filho','Drama','145 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/tEHOKQVW7Hw7T68uvJEUiJy13CR.jpg','available','Estante B6','Clara mora de frente para o mar no Aquarius, último prédio de estilo antigo da Av. Boa Viagem, no Recife. Jornalista aposentada e escritora, viúva com três filhos adultos e dona de um aconchegante apartamento repleto de discos e livros, ela irá enfrentar as investidas de uma construtora que tem outros planos para aquele terreno: demolir o Aquarius e dar lugar a um novo empreendimento.','Sonia Braga, Maeve Jinkings, Irandhir Santos, Humberto Carrão','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/veZzmysk4x3clDOsXiAADWVjL40.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (15,'VT-0015','Que Horas Ela Volta?','Que Horas Ela Volta?',2015,'Anna Muylaert','Drama','112 min','English','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/pLtU6oXgLmw3MweUMIALDlJYYDk.jpg','available','Estante B7','A pernambucana Val (Regina Casé) se mudou para São Paulo a fim de dar melhores condições de vida para sua filha Jéssica. Com muito receio, ela deixou a menina no interior de Pernambuco para ser babá de Fabinho, morando integralmente na casa de seus patrões. Treze anos depois, quando o menino (Michel Joelsas) vai prestar vestibular, Jéssica (Camila Márdila) lhe telefona, pedindo ajuda para ir à São Paulo, no intuito de prestar a mesma prova. Os chefes de Val recebem a menina de braços abertos, só que quando ela deixa de seguir certo protocolo, circulando livremente, como não deveria, a situação se complica.','Regina Casé, Camila Márdila, Karine Teles, Lourenço Mutarelli','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/9h5BsxRmxLAvASADo2VcTlTUdb0.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (16,'VT-0016','Tropa de Elite','Tropa de Elite',2007,'José Padilha','Drama','115 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/wFMkqerSlifIae2cja6K1fdvz2G.jpg','available','Estante B8','Rio de Janeiro, 1997. Nascimento, capitão da Tropa de Elite do Rio de Janeiro, é designado para chefiar uma das equipes que tem como missão "apaziguar" o Morro do Turano por um motivo que ele considera insensato. Mas ele tem que cumprir as ordens enquanto procura por um substituto. Sua mulher, Rosane, está no final da gravidez e todos os dias lhe pede para sair da linha de frente do batalhão. Pressionado, o capitão sente os efeitos do estresse.Neste clima, é chamado para mais uma emergência num morro. Em meio a um tiroteio em um baile funk, Nascimento e sua equipe têm que resgatar dois aspirantes a oficiais da PM: Neto e Matias. Ansiosos por entrar em ação e impressionados com a eficiência de seus salvadores, os dois se candidatam ao curso de formação da Tropa de Elite.','Wagner Moura, André Ramiro, Caio Junqueira, Milhem Cortaz','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/huUgrGkCetYSkDl5fMvZCXCbFKl.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (17,'VT-0017','Abril Despedaçado','Abril Despedaçado',2001,'Walter Salles','Drama','95 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/dWJLpe0bWf8bNSD6ec1e2xMtfU2.jpg','available','Estante C1','Uma família que sobrevive no  sertão através do cultivo de cana-de-açúcar está há tempos em guerra com a família da propriedade vizinha. O conflito dura tanto tempo que até mesmo um ritual meticuloso foi estabelecido, dando direitos de "cobrar o sangue" do familiar morto apenas após respeitado o tempo de luto. Tonho sofreu a morte do irmão mais velho, e agora tem a obrigação de vingar-se.','Rodrigo Santoro, José Dumont, Rita Assemany, Luiz Carlos Vasconcelos','France','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/9fKYqsnqDKvu2vRgTzJMTfPeBoc.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (18,'VT-0018','Lavoura Arcaica','Lavoura Arcaica',2001,'Luiz Fernando Carvalho','Romance','171 min','Português','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/orRApy2BHy99HyWf7PwzHtoZRd1.jpg','available','Estante C2','André (Selton Mello) é um filho desgarrado, que saiu de casa devido à severa lei paterna e o sufocamento da ternura materna. Pedro (Leonardo Medeiros), seu irmão mais velho, recebe de sua mãe a missão de trazê-lo de volta ao lar. Cedendo aos apelos da mãe e de Pedro, André resolve voltar para a casa dos seus pais, mas irá quebrar definitivamente os alicerces da família ao se apaixonar por sua bela irmã Ana (Simone Spoladore).','Selton Mello, Raul Cortez, Juliana Carneiro da Cunha, Simone Spoladore','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/BhLomNgO8x8CP5aAmXocmFFDfv.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (19,'VT-0019','Madame Satã','Madame Satã',2002,'Karim Aïnouz','Crime','100 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/73wB0Z8UlmVoOKbBZj5yhgsxK3U.jpg','available','Estante C3','Rio de Janeiro, 1932.  No bairro da Lapa vive encarcerado na prisão João Francisco (Lázaro Ramos), artista transformista que sonha em se tornar um grande astro dos palcos.  Após deixar o cárcere, João passa a viver com Laurita (Marcélia Cartaxo), prostituta e sua "esposa"; Firmina, a filha de Laurita; Tabu (Flávio Bauraqui), seu cúmplice; Renatinho (Felippe Marques), sem amante e também traidor; e ainda Amador (Emiliano Queiroz), dono do bar Danúbio Azul.  É neste ambiente que João Francisco irá se transformar no mito Madame Satã, nome retirado do filme (1932), dirigido por Cecil B. deMille, que João Francisco viu e adorou.','Lázaro Ramos, Marcélia Cartaxo, Flávio Bauraqui, Renata Sorrah','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/4xp2igbXfRYa7pWsBfsQQKqRRpE.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (20,'VT-0020','O Céu de Suely','O Céu de Suely',2006,'Karim Aïnouz','Drama','88 min','Português','Livre','Digital','https://image.tmdb.org/t/p/w500/e6vgJi5kae4awfI6uyzU1hLiiLK.jpg','available','Estante C4','Hermila (Hermila Guedes) é uma jovem de 21 anos que está de volta à sua cidade-natal, a pequena Iguatu, localizada no interior do Ceará. Ela volta juntamente com seu filho, Mateuzinho, e aguarda para daqui a algumas semanas a chegada de Mateus, pai da criança, que ficou em São Paulo para acertar assuntos pendentes. Porém o tempo passa e Mateus simplesmente desaparece. Querendo deixar o lugar de qualquer forma, Hermila tem uma idéia inusitada: rifar seu próprio corpo para conseguir dinheiro suficiente para comprar passagens de ônibus para longe e iniciar nova vida.','Hermila Guedes, João Miguel, Maria Menezes, Georgina Castro','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/8ZyLo0z8kYBFzrY6lnBYqb1qy0L.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (21,'VT-0021','Cabra Marcado para Morrer','Cabra Marcado Para Morrer',1984,'Eduardo Coutinho','Documentário','119 min','Español','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/fdll4h8DHM4W1AXDh44WlfvY1rC.jpg','available','Estante C5','Um camponês é assassinado e sua história vira tema de um filme. Porém, com o golpe de 1964, a filmagem é suspensa. Dezessete anos depois, o diretor retorna ao local e desperta questões que até então estavam adormecidas.','Eduardo Coutinho, Elizabeth Teixeira, Ferreira Gullar, Tite de Lemos','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/f8zh7tSRsp4h3tGaD6ZRRWANXSX.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (22,'VT-0022','Ainda Estou Aqui','Ainda Estou Aqui',2024,'Walter Salles','Drama','135 min','Português','Livre','DVD','https://image.tmdb.org/t/p/w500/zNAw7jK8bwCK56rIW676pdgkwhd.jpg','available','Estante C6','No início da década de 1970, o Brasil enfrenta o endurecimento da ditadura militar. No Rio de Janeiro, a família Paiva – Rubens, Eunice e seus cinco filhos – vive à beira da praia em uma casa de portas abertas para os amigos. Um dia, Rubens Paiva é levado por militares à paisana e desaparece.','Fernanda Torres, Fernanda Montenegro, Selton Mello, Valentina Herszage','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/j9uruwRe9qM8RnP758dF7ISB8Bj.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (23,'VT-0023','A Vida Invisível','A Vida Invisível',2019,'Karim Aïnouz','Drama','139 min','ελληνικά','Livre','Digital','https://image.tmdb.org/t/p/w500/p5Ia6cQXeJRjnHMBmZx0JF9JSwc.jpg','available','Estante C7','Antigas cartas de sua irmã Guida, há muito desaparecida, surpreendem Eurídice, uma senhora de 80 anos. No Rio de Janeiro dos anos 1950, Guida e Eurídice são cruelmente separadas, impedidas de viverem os sonhos que alimentaram juntas ainda adolescentes.','Carol Duarte, Julia Stockler, Fernanda Montenegro, Gregório Duvivier','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/u2Av6NyDeLkwYTBXxIGousLNzz.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (24,'VT-0024','Marte Um','Marte Um',2022,'Gabriel Martins','Drama','115 min','Português','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/nBp6ekvZHV8oSQu8gpzj6ncM3L2.jpg','available','Estante C8','Uma família de classe média baixa passa por uma série de mudanças profundas e desafiadoras, reinventando a si mesmos e os seus laços familiares durante o processo. Tércia, a mãe, reinterpreta seu mundo depois que um encontro inesperado a deixa se perguntando se ela é amaldiçoada. Seu marido, Wellington, coloca todas as suas esperanças na carreira de seu filho, Deivinho, que relutantemente segue as ambições de seu pai, apesar de secretamente aspirar a estudar astrofísica e colonizar Marte. Enquanto isso, sua filha mais velha, Eunice, se apaixona por uma jovem de espírito livre e pondera se é hora de sair de casa.','Cícero Lucas, Rejane Faria, Carlos Francisco, Camilla Damião','Brazil','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/mYA6m2kruLxmqAApVcX8uMc0jNJ.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (25,'VT-0025','Cidadão Kane','Citizen Kane',1941,'Orson Welles','Mistério','119 min','English','Livre','DVD','https://image.tmdb.org/t/p/w500/2pJ2voOH3QqfgDygG6e9W48YBLt.jpg','available','Estante D1','O magnata da imprensa Charles Foster Kane é tirado de sua mãe ainda menino e colocado sob a tutela de um rico industrial. Como resultado, cada movimento bem-intencionado, tirânico ou autodestrutivo que ele faz pelo resto da vida parece ser, de alguma forma, uma reação a esse evento profundamente traumático.','Orson Welles, Joseph Cotten, Dorothy Comingore, Ray Collins','United States of America','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/ruF3Lmd4A8MHbnEBE6lxPMbsHGL.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (26,'VT-0026','Um Corpo que Cai','Vertigo',1958,'Alfred Hitchcock','Mistério','128 min','English','Livre','Digital','https://image.tmdb.org/t/p/w500/lzyh1lsD4Qaid6bG5zk57Y3bEM.jpg','maintenance','Estante D2','O ex-detetive da polícia de São Francisco, John "Scottie" Ferguson, se aposenta da corporação após desenvolver acrofobia e vertigem. Ele é procurado por um antigo conhecido, Gavin Elster, que o contrata para seguir sua esposa, Madeleine, cujo comportamento tem se tornado cada vez mais errático. Conforme Scottie investiga, ele se vê envolvido em um mistério complexo e perturbador que desafia suas percepções de realidade, identidade e obsessão.','James Stewart, Kim Novak, Barbara Bel Geddes, Tom Helmore','United States of America','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/rtVwkTqllcmyY4TVOycgVBHppWf.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (27,'VT-0027','Os Incompreendidos','Les Quatre Cents Coups',1959,'François Truffaut','Drama','99 min','English','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/wHITh5qpAZr9e9Q7mtxXYReJxt2.jpg','available','Estante D3','Para o jovem parisiense Antoine Doinel, a vida é uma sucessão de dificuldades. Cercado por adultos insensíveis, incluindo seus pais negligentes, Antoine passa os dias com seu melhor amigo, René, tentando planejar uma vida melhor. Quando um de seus planos dá errado, Antoine acaba se metendo em problemas com a lei, o que leva a ainda mais conflitos com figuras de autoridade insensíveis.','Jean-Pierre Léaud, Claire Maurier, Albert Rémy, Georges Flamant','France','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/9w0Kk8Sleb4tkCFEUcvibMzaa16.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (28,'VT-0028','Acossado','À bout de souffle',1960,'Jean-Luc Godard','Drama','90 min','Français','Livre','DVD','https://image.tmdb.org/t/p/w500/duTBwrPiJV75xGSzq1Xe68UCrdw.jpg','available','Estante D4','Após roubar um carro em Marselha, Michel Poiccard (Jean-Paul Belmondo) ruma para Paris. No caminho mata um policial, que tentou prendê-lo por excesso de velocidade, e em Paris persuade a relutante Patricia Franchisi (Jean Seberg), uma estudante americana com quem se envolveu, para escondê-lo até receber o dinheiro que lhe devem. Michel promete a Patricia que irão juntos para a Itália. No entanto, o crime de Michel está nos jornais e agora não há opção. Ele fica escondido no apartamento de Patricia, onde conversam, namoram, ele fala sobre a morte e ela diz que quer ficar grávida dele. Ele perde a consciência da situação na qual se encontra e anda pela cidade cometendo pequenos delitos, mas quando é visto por um informante começa o final da sua trágica perseguição.','Jean-Paul Belmondo, Jean Seberg, Daniel Boulanger, Henri-Jacques Huet','France','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/4WGuyWf1f94CsEeVIIqDKGw5rmO.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (29,'VT-0029','8½','8½',1963,'Federico Fellini','Drama','139 min','Deutsch','Livre','Digital','https://image.tmdb.org/t/p/w500/nQkrZRxnvrkb6BV7ZYmdwJoFGDt.jpg','available','Estante D5','Prestes a rodar sua próxima obra, o cineasta Guido Anselmi ainda não tem idéia de como será o filme. Mergulhado em uma crise existencial e pressionado pelo produtor, pela mulher, pela amante e pelos amigos, ele se interna em uma estação de águas e passa a misturar o passado com o presente, ficção com realidade.','Marcello Mastroianni, Claudia Cardinale, Anouk Aimée, Sandra Milo','Italy','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/y2FNZLHynsevBnVTocGW6c3pQpr.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (30,'VT-0030','Rashomon','羅生門',1950,'Akira Kurosawa','Crime','88 min','日本語','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/wNCx5AdhBgSn0ddva3SEUFLs81K.jpg','available','Estante D6','No Japão do século XI, um lenhador, um sacerdote e um camponês procuram refúgio de uma tempestade nas ruínas de pedra do Portão de Rashomon. O sacerdote conta detalhes de um julgamento que testemunhou, envolvendo o estupro de Masako e o assassinato do marido dela, Takehiro, um samurai. Em flashback é mostrado o julgamento do bandido Tajomaru, onde acontecem quatro testemunhos, inclusive de Takehiro através de um médium. Cada um é uma "verdade", que entra em conflito com as outras.','Toshirô Mifune, Machiko Kyō, 志村喬, Masayuki Mori','Japan','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/tDn1dA52bQH9B85vilHeU7C83W1.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (31,'VT-0031','Era uma Vez em Tóquio','東京物語',1953,'Yasujiro Ozu','Drama','137 min','English','Livre','DVD','https://image.tmdb.org/t/p/w500/4HCbmramVjhtwvPzoRGXiPhu9Zk.jpg','available','Estante D7','Um casal de idosos deixa sua filha no campo para visitar os outros filhos em Tóquio, cidade que eles nunca tinham ido. Porém os filhos os recebem com indiferença, e estão sempre muito atarefados para terem tempo para os pais. Apenas a nora deles, que perdeu o marido na guerra, parece dar atenção aos dois. Quando a mãe fica doente, os filhos vão visitá-la junto com a nora, e complexos sentimentos são revelados.','Chishu Ryu, 東山千栄子, Setsuko Hara, 杉村春子','Japan','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/jLq0ol1f0ZKXni9R9GsPBcyPrNN.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (32,'VT-0032','O Encouraçado Potemkin','Броненосец Потёмкин',1925,'Serguei Eisenstein','Drama','72 min','No Language','Livre','Digital','https://image.tmdb.org/t/p/w500/a1AvYpBbEixfNK6KgG5bpowsm7X.jpg','available','Estante D8','Em 1905, na Rússia czarista, aconteceu um levante que pressagiou a Revolução de 1917. Tudo começou no navio de guerra Potemkin quando os marinheiros estavam cansados de serem maltratados, sendo que até carne estragada lhes era dada com o médico de bordo insistindo que ela era perfeitamente comestível. Alguns marinheiros se recusam em comer esta carne, então os oficiais do navio ordenam a execução deles. A tensão aumenta e, gradativamente, a situação sai cada vez mais do controle. Logo depois dos gatilhos serem apertados Vakulinchuk (Aleksandr Antonov), um marinheiro, grita para os soldados e pede para eles pensarem e decidirem se estão com os oficiais ou com os marinheiros. Os soldados hesitam e então abaixam suas armas. Louco de ódio, um oficial tenta agarrar um dos rifles e provoca uma revolta no navio, na qual o marinheiro é morto. Mas isto seria apenas o início de uma grande tragédia.','Александр Антонов, Владимир Барский, Grigoriy Aleksandrov, Иван Бобров','Soviet Union','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/3RH61Z7BP3f215936PJBEG2qQrT.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (33,'VT-0033','Metrópolis','Metropolis',1927,'Fritz Lang','Drama','153 min','No Language','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/xBx21HvGJCb15PKWkyb7uc435Wx.jpg','available','Estante E1','O futuro ė distante e o mundo está sob o comando dos poderosos, que isolaram os mais pobres no subsolo como se fossem seus escravos, para que trabalhassem em prol dos mesmos. Comandados por Freder Fredersen, os operários são obrigados a trabalharem sem parar para que a cidade não pare.','Gustav Fröhlich, Brigitte Helm, Alfred Abel, Rudolf Klein-Rogge','Germany','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/eeMoFKxjjiCi6iep2GEZtSAMYIr.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (34,'VT-0034','Ladrões de Bicicleta','Ladri di biciclette',1948,'Vittorio De Sica','Drama','90 min','Italiano','Livre','DVD','https://image.tmdb.org/t/p/w500/8hpVv2G8cXXEBp67dkcLNqrjNUs.jpg','available','Estante E2','Desempregado Antonio Ricci (Lamberto Maggiorani) está eufórico quando finalmente encontra trabalho colocando cartazes pela cidade de Roma, destruída pela guerra. Sua esposa Maria (Lianella Carell), vende os lençóis da família para resgatar a bicicleta de Antonio da loja de penhor, para que ele possa aceitar o trabalho. Porém, o desastre ataca, quando a bicicleta de Antonio é roubada. (e 10 - Estimado 10 Anos)','Lamberto Maggiorani, Enzo Staiola, Lianella Carell, Gino Saltamerenda','Italy','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/kTUUiKGKrdRhJsCcYT3Ivtfuuzh.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (35,'VT-0035','Persona','Persona',1966,'Ingmar Bergman','Drama','85 min','svenska','Livre','Digital','https://image.tmdb.org/t/p/w500/pMlIFOHnNDa3X0kSpjASn75KAYd.jpg','available','Estante E3','Uma atriz teatral de sucesso sofre uma crise emocional e para de falar. Uma enfermeira é designada a cuidar dela em uma casa reclusa, perto da praia, onde as duas permanecem sozinhas. Para quebrar o silêncio, a enfermeira começa a falar incessantemente, narrando diversos episódios relevantes de sua vida, mas quando descobre que a atriz usa seus depoimentos como fonte de análise, a cumplicidade entre as duas se transforma em embate.','Bibi Andersson, Liv Ullmann, Margaretha Krook, Gunnar Björnstrand','Sweden','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/amr72SENYz7AM4Hq5WBXxFBJEY6.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (36,'VT-0036','Amor à Flor da Pele','花樣年華',2000,'Wong Kar-wai','Drama','99 min','广州话 / 廣州話','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/yCKaf65zoySg2iJdsews4Rafl7C.jpg','available','Estante E4','Ambientado em Hong Kong no início dos anos 60, dois vizinhos, Sr. Chow e Sra. Chan, criam um vínculo depois de começarem a suspeitar que seus respectivos cônjuges estão tendo um caso juntos.','Maggie Cheung, Tony Chiu-Wai Leung, 萧炳林, 潘迪华','Hong Kong','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/ffQFnAUm2Uu4RU0nijpjPRf9TBT.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (37,'VT-0037','A Viagem de Chihiro','千と千尋の神隠し',2001,'Hayao Miyazaki','Animação','125 min','日本語','Livre','DVD','https://image.tmdb.org/t/p/w500/hhoKhsyJ3hFaxEm5pMdZRiTu2lJ.jpg','available','Estante E5','Chihiro e seus pais estão se mudando para uma cidade diferente. A caminho da nova casa, o pai decide pegar um atalho. Eles se deparam com uma mesa repleta de comida, embora ninguém esteja por perto. Chihiro sente o perigo, mas seus pais começam a comer. Quando anoitece, eles se transformam em porcos. Agora, apenas Chihiro pode salvá-los.','Rumi Hiiragi, Miyu Irino, Mari Natsuki, Takashi Naitô','Japan','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/m4TUa2ciEWSlk37rOsjiSIvZDXE.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (38,'VT-0038','Roma','Roma',2018,'Alfonso Cuarón','Drama','135 min','Español','Livre','Digital','https://image.tmdb.org/t/p/w500/veWGVw33lnifG10fpkz3QmimVaI.jpg','available','Estante E6','Na década de 1970, uma jovem trabalhadora doméstica indígena Cleodegaria "Cleo" Gutiérrez trabalha para uma família abastada de classe média do bairro de Roma, Cidade do México. À medida que as lutas domésticas e as restrições da hierarquia social se desdobram em meio a um pano de fundo de poderosos terremotos, revoltas estudantis e agitação política, a família luta para permanecer unida enquanto essas forças ameaçam separá-los.','Yalitza Aparicio, Marina de Tavira, Diego Cortina Autrey, Carlos Peralta','United Kingdom','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/zl9uqCl5iUSb50sTk2BPzw6bJnU.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (39,'VT-0039','Moonlight: Sob a Luz do Luar','Moonlight',2016,'Barry Jenkins','Drama','111 min','English','Livre','Blu-ray','https://image.tmdb.org/t/p/w500/AekOkoT88EhDHikUQXQcKri2q4B.jpg','maintenance','Estante E7','Moonlight narra a vida de um jovem gay afro-americano, desde a infância até a vida adulta e sua luta para encontrar seu lugar no mundo enquanto cresce num bairro violento de Miami. Ao mesmo tempo um retrato essencial da vida contemporânea do afro-americano e uma reflexão intensa, pessoal e poética sobre identidade, família e amizade. A direção de Barry Jenkins traz sua visão única e profundamente comovente sobre o caleidoscópio de momentos, pessoas e forças desconhecidas que determinam nossas vidas e nos fazem ser quem somos.','Trevante Rhodes, André Holland, Janelle Monáe, Ashton Sanders','United States of America','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/jm1oD3eB08LImSwL1LrzF9AJQ5b.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO films (id,internal_code,title,original_title,year,director,genre,duration,language,rating,media,cover,status,location,synopsis,"cast",country,rights_status,rights_holder,license_type,rights_valid_until,rights_notes,backdrop) VALUES (40,'VT-0040','Retrato de uma Jovem em Chamas','Portrait de la jeune fille en feu',2019,'Céline Sciamma','Drama','122 min','Italiano','Livre','DVD','https://image.tmdb.org/t/p/w500/c3OkDxs7PQuLB12qiwZUDg7ZMO6.jpg','available','Estante E8','França, 1760. Marianne é contratada para pintar o retrato de casamento de Héloïse, uma jovem mulher que acabou de deixar o convento. Por ela ser uma noiva relutante, Marianne chega sob o disfarce de companhia, observando Héloïse de dia e a pintando secretamente à noite. Conforme as duas mulheres se aproximam, a intimidade e a atração crescem, enquanto compartilham os primeiros e últimos momentos de liberdade de Héloïse, antes do casamento iminente. O retrato de Héloïse logo se torna um ato colaborativo e o testamento do amor delas.','Noémie Merlant, Adèle Haenel, Luàna Bajrami, Valeria Golino','France','authorized','Licença institucional (simulada)','exibicao_publica',(NOW() + INTERVAL '1 year')::date,'Acervo de demonstração','https://image.tmdb.org/t/p/w1280/ivJ5UzT6IzucLVfbZwCCwiJJoBz.jpg') ON CONFLICT (internal_code) DO UPDATE SET cover=EXCLUDED.cover, backdrop=EXCLUDED.backdrop, synopsis=EXCLUDED.synopsis, director=EXCLUDED.director, genre=EXCLUDED.genre, duration=EXCLUDED.duration, original_title=EXCLUDED.original_title, "cast"=EXCLUDED."cast";
INSERT INTO film_rights_proofs (film_id, filename, media_type, content, sha256) SELECT f.id, 'licenca-' || f.internal_code || '.pdf', 'application/pdf', c, encode(sha256(c), 'hex') FROM films f CROSS JOIN LATERAL (SELECT convert_to('%PDF-1.4 licenca ficticia ' || f.internal_code, 'UTF8') AS c) s WHERE f.internal_code LIKE 'VT-%' AND f.rights_status = 'authorized' AND NOT EXISTS (SELECT 1 FROM film_rights_proofs p WHERE p.film_id = f.id);
